const scoreScale={"c":1.0,"h":1.00434544,"u":1.37233757,"m":1.37470135,"r":1.38984323,"s":1.38756959,"k":1.19623811};
const scoreOffset={"c":-0.00314108,"h":0.02017085,"u":-0.05577156,"m":-0.07083469,"r":0.04504279,"s":0.05686553,"k":0.00766816};
function calculateResult(answers){
 if(answers.length!==questions.length||answers.some(a=>!Number.isInteger(a)||a<0||a>2))throw new Error(`${questions.length}개의 답변이 필요합니다.`);
 const ids=Object.keys(characters),scores=Object.fromEntries(ids.map(id=>[id,0])),primary={...scores};
 answers.forEach((a,i)=>{const[p,s]=questions[i].weights[a];scores[p]+=2;scores[s]++;primary[p]++;});
 ids.forEach(id=>{scores[id]=scores[id]*scoreScale[id]+scoreOffset[id];});
 let candidates=ids.filter(id=>scores[id]===Math.max(...Object.values(scores)));
 candidates=candidates.filter(id=>primary[id]===Math.max(...candidates.map(c=>primary[c])));
 for(const i of [3,7,6,5,2,1,0,4,8,9]){if(candidates.length===1)break;const[p,s]=questions[i].weights[answers[i]],value=id=>id===p?2:id===s?1:0;const max=Math.max(...candidates.map(value));candidates=candidates.filter(id=>value(id)===max);}
 return candidates[0];
}
